    motion: { pace: 1.1, headline: { preset: 'text-typewriter' }, text: { preset: 'fade', params: { y: 0 } }, shape: { preset: 'grow', params: { axis: 'x', origin: 'start' } }, exit: { preset: 'fade', params: { y: 0 } }, textAlt: [{ preset: 'wipe', params: { from: 'left' } }], shapeAlt: [{ preset: 'wipe', params: { from: 'top' } }], easeIn: 'power2.inOut', easeOut: 'power2.in' },
    sounds: { enter: 'tick', exit: 'swish', hit: 'click', accent: 'tick', density: 'light' },
    sample: { kicker: 'Fig. 1  ·  Scale 1:20', headline: 'How it fits together.', sub: 'Every part, measured and named.' },
    guide: { signs: 'Deep blue paper with a fine white grid; everything in thin white lines (no fills, or a faint white tint); dimension lines with end ticks and measurements in a mono font, labels in drafting capitals, numbered callouts with leader lines; one highlight colour (yellow) for the part being explained; parts slide apart along straight axes (an exploded view).', build: 'The grid is the stage background. Draw objects as path layers (stroke 0.2-0.3, white, no fill) with the draw preset, outer outline first, details after. Dimension lines: a thin path with ticks at both ends plus a small mono label that fades in when the line is drawn. Callouts: a numbered circle (pop) with a leader line (draw). For an exploded view, group each part and slide it outward along one axis (slide or drift, power2.inOut). Highlight the part being explained by recolouring its lines yellow (accent2). No shadows, no gradients on parts, no bouncy easing.' },
    signature: { preset: 'text-outline', params: { width: 0.1, color: '#ffffff' } },
